using Godot;

public partial class GongfaTree : Control
{
    [Signal] public delegate void RouteRequestedEventHandler(string chapter_id, string route_name, bool enabled);
    [Signal] public delegate void ChapterRequestedEventHandler(string chapter_id, bool learned);
    private Character? _human; private GongfaResource? _gongfa; private bool _isMain=true; private float _pulse; private Texture2D? _branchPlaque; private readonly List<(Rect2 rect,string chapter,string route,bool enabled)> _hits=[]; private readonly List<(Rect2 rect,string chapter,bool learned)> _chapterHits=[];
    public override void _Ready(){MouseFilter=MouseFilterEnum.Stop;CustomMinimumSize=new Vector2(760,440);GuiInput+=Input;_branchPlaque=GD.Load<Texture2D>("res://textures/ui/gongfa_branch_node_v1.png");}
    public override void _Process(double delta){_pulse+=(float)delta;QueueRedraw();}
    public void configure(Character human,GongfaResource? gongfa,bool is_main=true){_human=human;_gongfa=gongfa;_isMain=is_main;QueueRedraw();}
    public override void _Draw()
    {
        _hits.Clear(); _chapterHits.Clear(); if(_gongfa is null){DrawString(ThemeDB.FallbackFont,new Vector2(30,50),"尚未装配功法",HorizontalAlignment.Left,-1,20,new Color("6c6257"));return;}
        var chapters=_gongfa.get_sorted_chapters(); var cx=Size.X*.5f; var step=Mathf.Clamp((Size.Y-112)/Mathf.Max(chapters.Count,1),76,112); var top=60f;
        DrawString(ThemeDB.FallbackFont,new Vector2(28,34),$"《{_gongfa.gongfa_name}》 · {(_isMain?"主修":"辅修")}",HorizontalAlignment.Left,-1,21,new Color("2b241a"));
        if(chapters.Count>1)DrawLine(new Vector2(cx,top),new Vector2(cx,top+(chapters.Count-1)*step),new Color(.20f,.18f,.14f,.56f),3);
        for(var i=0;i<chapters.Count;i++){var chapter=chapters[i];var y=top+i*step;var learned=_human?.is_gongfa_chapter_learned(_gongfa,chapter.get_id())??false;var span=Mathf.Min(Size.X*.31f,210);var line=learned?new Color(.24f,.21f,.15f,.72f):new Color(.25f,.23f,.19f,.24f);var origin=new Vector2(cx,y);var leftEnd=new Vector2(cx-span+52,y);var rightEnd=new Vector2(cx+span-52,y);DrawLine(new Vector2(cx-12,y),leftEnd,line,3);DrawLine(new Vector2(cx+12,y),rightEnd,line,3);if(learned){var activeLeft=_isMain||_human?.get_sub_gongfa_chapter_route(_gongfa,chapter.get_id())=="left";var activeRight=_isMain||_human?.get_sub_gongfa_chapter_route(_gongfa,chapter.get_id())=="right";if(activeLeft)Flow(origin+Vector2.Left*12,leftEnd);if(activeRight)Flow(origin+Vector2.Right*12,rightEnd);}DrawCircle(origin,13,learned?new Color(.63f,.46f,.23f,.92f):new Color(.35f,.32f,.27f,.54f));DrawString(ThemeDB.FallbackFont,new Vector2(cx-42,y+34),chapter.chapter_name,HorizontalAlignment.Center,84,14,new Color("2b241a"));_chapterHits.Add((new Rect2(origin-new Vector2(54,28),new Vector2(108,60)),chapter.get_id(),learned));Route(new Vector2(cx-span,y),chapter,string.IsNullOrWhiteSpace(chapter.left_branch_name)?"纳气":chapter.left_branch_name,"left",learned);Route(new Vector2(cx+span,y),chapter,string.IsNullOrWhiteSpace(chapter.right_branch_name)?"化法":chapter.right_branch_name,"right",learned);}
    }
    private void Route(Vector2 center,GongfaChapterConfig chapter,string label,string route,bool learned){var rect=new Rect2(center-new Vector2(65,30),new Vector2(130,60));var selected=_isMain||(_human?.get_sub_gongfa_chapter_route(_gongfa!,chapter.get_id())==route);var tint=!learned?new Color(1,1,1,.36f):selected?new Color(1,0.92f,.65f,.92f):new Color(1,1,1,.82f);if(_branchPlaque is not null)DrawTextureRect(_branchPlaque,rect.Grow(10),false,tint);else DrawRect(rect,new Color("d9c7a2"));if(selected&&learned){var glow=.62f+.28f*Mathf.Sin(_pulse*2.2f);DrawCircle(center,30,new Color(.82f,.58f,.20f,.16f*glow));}DrawString(ThemeDB.FallbackFont,new Vector2(rect.Position.X,rect.Position.Y+29),label,HorizontalAlignment.Center,rect.Size.X,17,learned?new Color("211b14"):new Color(.25f,.23f,.19f,.55f));DrawString(ThemeDB.FallbackFont,new Vector2(rect.Position.X,rect.Position.Y+48),!learned?"境界或前卷未达":_isMain?"主修生效":selected?"已启用":"点击启用",HorizontalAlignment.Center,rect.Size.X,11,new Color(.25f,.22f,.16f,.76f));_hits.Add((rect,chapter.get_id(),route,learned));}
    private void Flow(Vector2 from,Vector2 to){var phase=Mathf.PosMod(_pulse*.42f,1f);var dot=from.Lerp(to,phase);var glow=.68f+.26f*Mathf.Sin(_pulse*4f);DrawCircle(dot,5,new Color(.92f,.68f,.28f,.34f*glow));DrawCircle(dot,2.2f,new Color(1f,.88f,.57f,.92f));}
    private void Input(InputEvent e){if(e is InputEventMouseButton {ButtonIndex:MouseButton.Left,Pressed:true} click){foreach(var hit in _chapterHits)if(hit.rect.HasPoint(click.Position)){EmitSignal(SignalName.ChapterRequested,hit.chapter,hit.learned);AcceptEvent();return;}foreach(var hit in _hits)if(hit.rect.Grow(10).HasPoint(click.Position)){EmitSignal(SignalName.RouteRequested,hit.chapter,hit.route,hit.enabled);AcceptEvent();return;}}}
}
